Lemma bn_brk_query : forall ms model K,
  m_halted model = None -> m_vm_lazy model = [] ->
  cj_at_node segs (NBrk 0) ms ->
  srealizes segs scfg (mkCfg (nret ms (mkEffectU (vm_brk (m_vmmaps model)) [] [] [] [] [])) model) K ->
